import XCTest

final class DriverTests: XCTestCase {

    let logPath = "/tmp/driver.log"

    func log(_ s: String) {
        let line = s + "\n"
        if let h = FileHandle(forWritingAtPath: logPath) {
            h.seekToEndOfFile()
            h.write(line.data(using: .utf8)!)
            h.closeFile()
        } else {
            FileManager.default.createFile(atPath: logPath, contents: line.data(using: .utf8))
        }
    }

    func find(_ app: XCUIApplication, _ label: String) -> XCUIElement? {
        if app.staticTexts[label].count > 0 { return app.staticTexts[label].firstMatch }
        if app.buttons[label].count > 0 { return app.buttons[label].firstMatch }
        if app.cells[label].count > 0 { return app.cells[label].firstMatch }
        if app.otherElements[label].count > 0 { return app.otherElements[label].firstMatch }
