    func testDrive() throws {
        let app = XCUIApplication(bundleIdentifier: "im.vector.app")
        app.activate()
        Thread.sleep(forTimeInterval: 1.0)
        let script = ProcessInfo.processInfo.environment["SCRIPT"] ?? "dump:/tmp/hier.txt"
        log("START script=\(script)")
        for raw in script.components(separatedBy: "|") {
            let cmd = raw.trimmingCharacters(in: .whitespaces)
            if cmd.isEmpty { continue }
            if cmd.hasPrefix("dump:") {
                let path = String(cmd.dropFirst(5))
                do {
                    try app.debugDescription.write(toFile: path, atomically: true, encoding: .utf8)
                    log("dumped \(path)")
                } catch {
                    log("dump error \(error)")
                }
            } else if cmd.hasPrefix("wait:") {
                let t = Double(cmd.dropFirst(5)) ?? 1
                Thread.sleep(forTimeInterval: t)
            } else if cmd.hasPrefix("tap:") {
                let label = String(cmd.dropFirst(4))
                if let el = find(app, label) {
                    if el.waitForExistence(timeout: 5) {
                        el.tap()
                        log("tapped \(label)")
                    } else {
                        log("notvisible \(label)")
                    }
                } else {
                    log("NOTFOUND \(label)")
                }
            } else if cmd.hasPrefix("forceTap:") {
                let label = String(cmd.dropFirst(9))
                if let el = find(app, label), el.waitForExistence(timeout: 5) {
                    let c = el.coordinate(withNormalizedOffset: CGVector(dx: 0.5, dy: 0.5))
                    c.tap()
                    log("forcetapped \(label)")
                } else {
                    log("NOTFOUND force \(label)")
                }
            } else if cmd == "swipeup" {
                app.swipeUp()
                log("swipeup")
            } else if cmd == "swipedown" {
                app.swipeDown()
                log("swipedown")
            } else if cmd.hasPrefix("type:") {
                let text = String(cmd.dropFirst(5))
                app.typeText(text)
                log("typed \(text)")
            } else {
                log("unknown cmd \(cmd)")
            }
        }
        log("END")
    }
}

